static UIViewController *Top(UIViewController *v){if(v.presentedViewController)return Top(v.presentedViewController);if([v isKindOfClass:UITabBarController.class])return Top(((UITabBarController *)v).selectedViewController);if([v isKindOfClass:UINavigationController.class])return Top(((UINavigationController *)v).topViewController);return v;}
static void Alert(UIViewController *v,NSString *title,NSString *text){UIAlertController *a=[UIAlertController alertControllerWithTitle:title message:text preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleCancel handler:nil]];[v presentViewController:a animated:YES completion:nil];}
@interface TFReceivePicker:UITableViewController<UISearchResultsUpdating>
@property NSArray *items;@property NSArray *filtered;@property(copy)void(^select)(NSDictionary *);
@end
@implementation TFReceivePicker
- (void)viewDidLoad{[super viewDidLoad];if(!self.title.length)self.title=@"选择目标";self.filtered=self.items;UISearchController *s=[[UISearchController alloc]initWithSearchResultsController:nil];s.searchResultsUpdater=self;s.obscuresBackgroundDuringPresentation=NO;self.navigationItem.searchController=s;}
- (void)updateSearchResultsForSearchController:(UISearchController *)s{NSString *q=s.searchBar.text;self.filtered=q.length?[self.items filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *r,NSDictionary *b){return [r[@"name"]?:r[@"title"] localizedCaseInsensitiveContainsString:q];}]]:self.items;[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.filtered.count;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *r=self.filtered[i.row];UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];c.textLabel.text=r[@"name"]?:r[@"title"];c.textLabel.numberOfLines=1;c.detailTextLabel.text=r[@"projectName"]?:([r[@"root"] length]?@"本机项目":@"普通会话");c.imageView.image=[UIImage systemImageNamed:r[@"root"]?@"folder":@"bubble.left"];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(self.select)self.select(self.filtered[i.row]);}
@end
@interface TFBinaryView:UITableViewController
@property NSString *query;@property NSString *address;@property NSDictionary *entry;@property NSArray *rows;@property NSString *action;@property NSDictionary *last;@property BOOL busy;@property NSUInteger offset;
@end
@implementation TFBinaryView
- (void)viewDidLoad{[super viewDidLoad];self.title=@"二进制分析";self.action=@"overview";self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithImage:[UIImage systemImageNamed:@"line.3.horizontal.decrease.circle"] style:UIBarButtonItemStylePlain target:self action:@selector(menu)];[self run];}
- (void)menu{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"本机只读分析" message:@"LLVM MC · 不执行动态库" preferredStyle:UIAlertControllerStyleActionSheet];NSArray *actions=@[@"overview",@"symbols",@"strings",@"disassemble",@"branches",@"headers"],*names=@[@"结构与加密范围",@"符号表",@"可读字符串",@"ARM64 反汇编",@"直接分支目标",@"导出 Objective-C 头文件"];for(NSUInteger i=0;i<actions.count;i++)[a addAction:[UIAlertAction actionWithTitle:names[i] style:UIAlertActionStyleDefault handler:^(id x){if(self.busy)return;self.action=actions[i];self.offset=0;[self run];}]];[a addAction:[UIAlertAction actionWithTitle:@"搜索 / 跳转地址" style:UIAlertActionStyleDefault handler:^(id x){UIAlertController *f=[UIAlertController alertControllerWithTitle:@"搜索与跳转" message:@"符号和字符串使用关键词；反汇编使用十六进制地址。留空恢复默认。" preferredStyle:UIAlertControllerStyleAlert];[f addTextFieldWithConfigurationHandler:^(UITextField *t){t.placeholder=@"符号或字符串关键词";t.text=self.query;}];[f addTextFieldWithConfigurationHandler:^(UITextField *t){t.placeholder=@"0x1000…";t.text=self.address;}];[f addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[f addAction:[UIAlertAction actionWithTitle:@"读取" style:UIAlertActionStyleDefault handler:^(id y){self.query=f.textFields[0].text;self.address=f.textFields[1].text;self.offset=0;[self run];}]];[self presentViewController:f animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItem;[self presentViewController:a animated:YES completion:nil];}
- (void)run{if(self.busy)return;self.busy=YES;UIActivityIndicatorView *spinner=[[UIActivityIndicatorView alloc]initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];[spinner startAnimating];self.tableView.backgroundView=spinner;NSMutableDictionary *args=[@{@"action":self.action,@"offset":@(self.offset),@"limit":@100} mutableCopy];if(self.query.length)args[@"query"]=self.query;if(self.address.length)args[@"address"]=self.address;dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;NSDictionary *r=TFAIBinaryExecute(self.entry[@"binaryInputID"],args,&error);dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;self.tableView.backgroundView=nil;self.last=r;NSMutableArray *rows=[NSMutableArray new];if(error)[rows addObject:error.localizedDescription];else if([r[@"items"] isKindOfClass:NSArray.class])for(NSDictionary *item in r[@"items"]){NSString *text=nil;if(item[@"instruction"])text=[NSString stringWithFormat:@"%@   %@%@",item[@"address"],item[@"instruction"],item[@"branchTarget"]?[NSString stringWithFormat:@"\n          → %@",item[@"branchTarget"]]:@""];else if(item[@"name"])text=[NSString stringWithFormat:@"%@\n%@ · %@",item[@"name"],item[@"address"], [item[@"type"] isEqual:@"undefined"]?@"导入符号":@"已定义符号"];else text=[NSString stringWithFormat:@"%@\n%@ · %@",item[@"text"]?:@"",item[@"address"]?:@"",item[@"section"]?:@""];[rows addObject:text];}else if(r[@"cpu"]){[rows addObject:[NSString stringWithFormat:@"架构  %@\n大小  %@\nUUID  %@\n安装名  %@",r[@"cpu"],[NSByteCountFormatter stringFromByteCount:[r[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile],r[@"uuid"],r[@"installName"]]];[rows addObject:[r[@"encrypted"] boolValue]?@"检测到映像加密范围，指令读取会停止。":@"未发现映像加密标记；字符串仍可能经过单独编码或混淆。"];for(NSDictionary *c in r[@"encryptionRanges"])[rows addObject:[NSString stringWithFormat:@"加密区间  偏移 %@ · 长度 %@ · cryptid %@",c[@"offset"],c[@"size"],c[@"cryptid"]]];for(NSString *d in r[@"dependencies"])[rows addObject:[@"依赖  " stringByAppendingString:d]];for(NSDictionary *sec in r[@"sections"])[rows addObject:[NSString stringWithFormat:@"%@ / %@\n地址 0x%llx · %llu 字节",sec[@"segment"],sec[@"name"],[sec[@"address"] unsignedLongLongValue],[sec[@"size"] unsignedLongLongValue]]];}else [rows addObject:[NSString stringWithFormat:@"已导出 %@ 个头文件\n%@",r[@"headers"]?:@"",r[@"note"]?:@""]];if(!rows.count)[rows addObject:@"当前筛选没有结果。"];if([r[@"hasMore"] boolValue])[rows addObject:@"继续读取下一页…"];if([r[@"zipAvailable"] boolValue])[rows addObject:@"分享头文件 ZIP"];self.rows=rows;[self.tableView reloadData];});});}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.rows.count;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];c.textLabel.text=self.rows[i.row];c.textLabel.numberOfLines=0;c.textLabel.font=[UIFont monospacedSystemFontOfSize:12 weight:UIFontWeightRegular];c.textLabel.textColor=([self.action isEqual:@"disassemble"]||[self.action isEqual:@"branches"])?UIColor.systemTealColor:UIColor.labelColor;c.selectionStyle=UITableViewCellSelectionStyleDefault;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if([self.rows[i.row] isEqual:@"继续读取下一页…"]){self.offset=[self.last[@"next_offset"] unsignedIntegerValue];[self run];}else if([self.rows[i.row] isEqual:@"分享头文件 ZIP"]){NSURL *url=TFAIClassDumpExportURL(self.last[@"jobID"]);if(url){UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[url] applicationActivities:nil];share.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:share animated:YES completion:nil];}}else UIPasteboard.generalPasteboard.string=self.rows[i.row];}
@end
