@end
@implementation TFReceiveController
- (void)viewDidLoad{[super viewDidLoad];self.title=@"接收文件";self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemDone target:self action:@selector(close)];NSString *kind=self.record[@"kind"];NSMutableArray *a=[NSMutableArray new];if([@[@"project",@"archive"] containsObject:kind])[a addObject:@[@"folder.badge.plus",@"导入为新项目",@"识别源码、Makefile 和打包配置",@"newproject"]];if([kind isEqual:@"file"])[a addObject:@[@"folder.badge.plus",@"用此文件新建项目",@"加入源码后检查基础配置",@"newproject"]];if(![kind isEqual:@"ipa"])[a addObject:@[@"folder",@"添加到已有项目",@"保存到新目录，不覆盖原有文件",@"project"]];if([kind isEqual:@"binary"])[a addObject:@[@"waveform.path",@"打开分析工作台",@"LLVM 反汇编 · 符号 · 字符串 · 加密范围",@"binary"]];if([kind isEqual:@"ipa"])[a addObject:@[@"doc.text.magnifyingglass",@"导出 Objective-C 头文件",@"进入本机会话，通过工具解析后导出 ZIP",@"headers"]];[a addObject:@[@"sparkles",@"新建分析会话",@"作为待发送附件，不自动请求模型",@"newchat"]];[a addObject:@[@"bubble.left",@"添加到已有会话",@"选择目标会话，再添加到附件草稿",@"chat"]];self.actions=a;self.tableView.rowHeight=UITableViewAutomaticDimension;}
- (void)close{if(self.navigationController.viewControllers.firstObject!=self){[self.navigationController popViewControllerAnimated:YES];return;}UIViewController *host=self.navigationController.presentingViewController?:self.presentingViewController;[self dismissViewControllerAnimated:YES completion:^{TFIncomingDrain(host);}];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 2;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s?self.actions.count:1;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return s?@"文件副本已保存到 Incoming。附件不自动发送；AI 只按需读取工具返回结果。原文件不被修改。":nil;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{UITableViewCell *c=[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];c.detailTextLabel.numberOfLines=0;c.textLabel.numberOfLines=2;if(!i.section){c.textLabel.text=self.record[@"name"];c.detailTextLabel.text=[NSString stringWithFormat:@"%@\n%@ · 已存入本机",self.record[@"detail"],[NSByteCountFormatter stringFromByteCount:[self.record[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile]];c.imageView.image=[UIImage systemImageNamed:@"doc.zipper"];c.selectionStyle=UITableViewCellSelectionStyleNone;}else{NSArray *a=self.actions[i.row];c.textLabel.text=a[1];c.detailTextLabel.text=a[2];c.imageView.image=[UIImage systemImageNamed:a[0]];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;}return c;}
- (void)work:(id(^)(NSError **))block done:(void(^)(id))done{if(self.busy)return;self.busy=YES;MBProgressHUD *hud=[MBProgressHUD showHUDAddedTo:self.view animated:YES];hud.label.text=@"正在准备…";dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;id result=block(&error);dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;[hud hideAnimated:YES];if(!result){Alert(self,@"操作未完成",error.localizedDescription?:@"请检查文件类型和大小后重试。");return;}done(result);});});}
- (void)expand:(void(^)(NSString *))completion password:(NSString *)password{
 if(self.expanded){completion(self.expanded);return;}if(self.busy)return;self.busy=YES;
 NSString *out=[[self.record[@"path"] stringByDeletingLastPathComponent] stringByAppendingPathComponent:[@"Expanded-" stringByAppendingString:NSUUID.UUID.UUIDString]];
 MBProgressHUD *hud=[MBProgressHUD showHUDAddedTo:self.view animated:YES];hud.label.text=@"正在解压…";
 dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;BOOL ok=TMCExtractArchive([NSURL fileURLWithPath:self.record[@"path"]],[NSURL fileURLWithPath:out],password,nil,nil,&error);dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;[hud hideAnimated:YES];if(ok){self.expanded=out;[[NSJSONSerialization dataWithJSONObject:@{@"name":self.record[@"name"]?:@"分享文件"} options:0 error:nil] writeToFile:[out stringByAppendingPathComponent:@".tweakforge-display-name.json"] atomically:YES];completion(out);}else if(error.code==TMCArchivePassword){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"压缩包密码" message:@"密码仅用于本次本机解压。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *t){t.secureTextEntry=YES;t.placeholder=@"输入密码";}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"解压" style:UIAlertActionStyleDefault handler:^(id x){[self expand:completion password:a.textFields.firstObject.text];}]];[self presentViewController:a animated:YES completion:nil];}else Alert(self,@"解压未完成",error.localizedDescription);});});
}
- (void)prepareEntries:(void(^)(NSArray *))done{NSString *kind=self.record[@"kind"],*path=self.record[@"path"];if([kind isEqual:@"ipa"]){[self work:^id(NSError **e){NSDictionary *a=TFAIClassDumpStage([NSURL fileURLWithPath:path],e);return a?@[a]:nil;} done:done];}else if([kind isEqual:@"binary"]){[self work:^id(NSError **e){NSData *d=[NSData dataWithContentsOfFile:path options:NSDataReadingMappedIfSafe error:e];NSDictionary *ref=TFAIBinaryStage(d,path.lastPathComponent,e);if(!ref)return nil;NSString *text=@"本机二进制附件，使用 binary_inspect 按需分析，未上传二进制。";return @[@{@"kind":@"text",@"path":path.lastPathComponent,@"content":text,@"bytes":@([text lengthOfBytesUsingEncoding:NSUTF8StringEncoding]),@"binaryInputID":ref[@"binaryInputID"],@"sourceName":@"本机二进制"}];} done:done];}else if([@[@"headers",@"project",@"archive"] containsObject:kind]){[self expand:^(NSString *root){UIViewController *browser=TFAIAttachmentBrowser(root,@[@{@"root":root,@"name":self.record[@"name"]}],^(NSArray *entries){done(entries);});UINavigationController *n=[[TMCNavigationController alloc]initWithRootViewController:browser];[self presentViewController:n animated:YES completion:nil];} password:nil];}else TFAIImportAttachmentURLs(@[[NSURL fileURLWithPath:path]],^(NSArray *entries,NSError *error){if(error)Alert(self,@"附件未添加",error.localizedDescription);else done(entries);});}
- (void)target:(BOOL)project entries:(NSArray *)entries{NSArray *items=project?TFAIInternalProjects():[TFAISessions summaries:nil];if(!items.count){Alert(self,@"暂无目标",project?@"请先创建项目。":@"请先新建会话。可以返回选择“新建分析会话”。");return;}TFReceivePicker *picker=[[TFReceivePicker alloc]initWithStyle:UITableViewStyleInsetGrouped];picker.items=items;picker.select=^(NSDictionary *item){if(project)[self confirmCopy:item];else TFStudioReceiveAttachments(self,entries,item);};[self.navigationController pushViewController:picker animated:YES];}
- (void)confirmCopy:(NSDictionary *)project{NSString *path=self.record[@"path"],*kind=self.record[@"kind"],*folder=[@"Imported-" stringByAppendingString:[NSUUID.UUID.UUIDString substringToIndex:8]];UIAlertController *a=[UIAlertController alertControllerWithTitle:@"确认添加到项目？" message:[NSString stringWithFormat:@"%@\n目标：%@/\n%@\n保留两份，不覆盖原文件。构建 sources 和 include 路径不会自动更改，请在项目配置中检查。",project[@"name"],folder,self.record[@"name"]] preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"确认导入" style:UIAlertActionStyleDefault handler:^(id x){void(^copy)(NSString *)=^(NSString *source){[self work:^id(NSError **e){TMCGitLease *lease=[TMCGitLease tryWrite];if(!lease||[TMCGitLease isBuilding:project[@"root"]]){if(e)*e=[NSError errorWithDomain:@"Incoming" code:1 userInfo:@{NSLocalizedDescriptionKey:@"项目正在构建或处理 Git 操作，请稍后重试。"}];return nil;}NSString *root=[project[@"root"] stringByResolvingSymlinksInPath],*docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject.stringByResolvingSymlinksInPath;if(![root hasPrefix:[docs stringByAppendingString:@"/"]])return nil;NSString *dest=[root stringByAppendingPathComponent:folder];BOOL ok;if([source isEqual:path]){ok=[NSFileManager.defaultManager createDirectoryAtPath:dest withIntermediateDirectories:NO attributes:nil error:e]&&[NSFileManager.defaultManager copyItemAtPath:source toPath:[dest stringByAppendingPathComponent:path.lastPathComponent] error:e];}else ok=[NSFileManager.defaultManager copyItemAtPath:source toPath:dest error:e];(void)lease;return ok?dest:nil;} done:^(id result){Alert(self,@"已导入",[NSString stringWithFormat:@"已保存至 %@/。请检查项目 sources 和头文件搜索路径。",folder]);}];};if([@[@"project",@"archive",@"headers"] containsObject:kind])[self expand:copy password:nil];else copy(path);}]];[self.navigationController.topViewController presentViewController:a animated:YES completion:nil];}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(!i.section||self.busy)return;NSString *action=self.actions[i.row][3];if([action isEqual:@"newproject"]){UIViewController *host=self.presentingViewController;NSURL *url=[NSURL fileURLWithPath:self.record[@"path"]];BOOL archive=[@[@"archive",@"project"] containsObject:self.record[@"kind"]];[self dismissViewControllerAnimated:YES completion:^{TFStudioImportReceived(Top(host),url,archive);}];}else if([action isEqual:@"project"])[self target:YES entries:nil];else if([action isEqual:@"binary"])[self prepareEntries:^(NSArray *entries){[self.navigationController pushViewController:TFBinaryWorkbench(entries.firstObject) animated:YES];}];else [self prepareEntries:^(NSArray *entries){if([action isEqual:@"chat"])[self target:NO entries:entries];else TFStudioReceiveAttachments(self,entries,nil);}];}
@end
void TFIncomingPresent(UIViewController *host,NSDictionary *record){UIViewController *top=Top(host);if(top.presentedViewController)return;TFReceiveController *v=[[TFReceiveController alloc]initWithStyle:UITableViewStyleInsetGrouped];v.record=record;UINavigationController *nav=[[TMCNavigationController alloc]initWithRootViewController:v];nav.modalPresentationStyle=UIModalPresentationPageSheet;nav.modalInPresentation=YES;nav.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.largeDetent];[top presentViewController:nav animated:YES completion:nil];}
static NSMutableArray *Queue;static BOOL Staging;static NSURL *ActiveURL;
static void Process(UIViewController *host){if(Staging||!Queue.count)return;UIViewController *top=Top(host);if(top.presentingViewController||top.navigationController.presentingViewController||[top isKindOfClass:TFReceiveController.class]||[top isKindOfClass:TFReceivePicker.class])return;NSURL *url=Queue.firstObject;[Queue removeObjectAtIndex:0];Staging=YES;ActiveURL=url;MBProgressHUD *hud=[MBProgressHUD showHUDAddedTo:top.view animated:YES];hud.label.text=@"正在识别文件…";dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;NSDictionary *record=TFIncomingStage(url,&error);dispatch_async(dispatch_get_main_queue(),^{Staging=NO;ActiveURL=nil;[hud hideAnimated:YES];if(record){NSURL *group=TFShareContainer();NSString *base=[[group URLByAppendingPathComponent:@"TweakForgeShare/Pending"] path].stringByResolvingSymlinksInPath;if(base.length&&[url.path.stringByResolvingSymlinksInPath hasPrefix:[base stringByAppendingString:@"/"]])[NSFileManager.defaultManager removeItemAtURL:url error:nil];NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject;if([url.path.stringByDeletingLastPathComponent isEqual:docs]&&TFShareTransferOriginalName(url.lastPathComponent))[NSFileManager.defaultManager removeItemAtURL:url error:nil];TFIncomingPresent(host,record);}else Alert(top,@"文件接收失败",error.localizedDescription?:@"请重新分享文件。");});});}
void TFIncomingReceive(UIViewController *host,NSURL *url){if(!url.isFileURL||[ActiveURL isEqual:url])return;if(!Queue)Queue=[NSMutableArray new];if(Queue.count<20&&![Queue containsObject:url])[Queue addObject:url];Process(host);}
void TFIncomingDrain(UIViewController *host){if(!host||Staging)return;NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject;for(NSURL *url in TFShareTransferPending(docs)){if(!Queue)Queue=[NSMutableArray new];if(Queue.count<20&&![Queue containsObject:url]&&![ActiveURL isEqual:url])[Queue addObject:url];}NSURL *group=TFShareContainer();NSURL *pending=[group URLByAppendingPathComponent:@"TweakForgeShare/Pending"];if(pending){for(NSString *job in [NSFileManager.defaultManager contentsOfDirectoryAtPath:pending.path error:nil]){if(![[NSUUID alloc]initWithUUIDString:job])continue;NSString *jobPath=[pending.path stringByAppendingPathComponent:job];if(![[NSFileManager.defaultManager attributesOfItemAtPath:jobPath error:nil][NSFileType] isEqual:NSFileTypeDirectory])continue;for(NSString *folder in [NSFileManager.defaultManager contentsOfDirectoryAtPath:jobPath error:nil]){if(![[NSUUID alloc]initWithUUIDString:folder])continue;NSString *dir=[jobPath stringByAppendingPathComponent:folder];if(![[NSFileManager.defaultManager attributesOfItemAtPath:dir error:nil][NSFileType] isEqual:NSFileTypeDirectory])continue;for(NSString *file in [NSFileManager.defaultManager contentsOfDirectoryAtPath:dir error:nil]){NSURL *url=[NSURL fileURLWithPath:[dir stringByAppendingPathComponent:file]];if(!Queue)Queue=[NSMutableArray new];if(Queue.count<20&&![Queue containsObject:url])[Queue addObject:url];}}}}Process(host);}

UIViewController *TFIncomingHistory(void){TFReceivePicker *v=[[TFReceivePicker alloc]initWithStyle:UITableViewStyleInsetGrouped];v.items=@[];v.title=@"接收的文件";__weak TFReceivePicker *weak=v;v.select=^(NSDictionary *r){TFReceiveController *page=[[TFReceiveController alloc]initWithStyle:UITableViewStyleInsetGrouped];page.record=r;[weak.navigationController pushViewController:page animated:YES];};dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSString *base=[NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject stringByAppendingPathComponent:@"Incoming"];NSMutableArray *items=[NSMutableArray new];for(NSString *identifier in [NSFileManager.defaultManager contentsOfDirectoryAtPath:base error:nil]){if(![[NSUUID alloc]initWithUUIDString:identifier])continue;NSString *dir=[base stringByAppendingPathComponent:identifier];if(![[NSFileManager.defaultManager attributesOfItemAtPath:dir error:nil][NSFileType] isEqual:NSFileTypeDirectory])continue;NSData *d=[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:@"receipt.json"]];NSDictionary *r=d?[NSJSONSerialization JSONObjectWithData:d options:0 error:nil]:nil;if(![r isKindOfClass:NSDictionary.class]||![r[@"bytes"] isKindOfClass:NSNumber.class]||![r[@"receivedAt"] isKindOfClass:NSNumber.class]||![r[@"detail"] isKindOfClass:NSString.class]||![r[@"kind"] isKindOfClass:NSString.class]||![r[@"name"] isKindOfClass:NSString.class]||![r[@"name"] isEqual:[r[@"name"] lastPathComponent]])continue;NSString *path=[dir stringByAppendingPathComponent:r[@"name"]];if(![[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil][NSFileType] isEqual:NSFileTypeRegular])continue;NSMutableDictionary *entry=[r mutableCopy];entry[@"path"]=path;[items addObject:entry];} [items sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [b[@"receivedAt"] compare:a[@"receivedAt"]];}];dispatch_async(dispatch_get_main_queue(),^{weak.items=items;weak.filtered=items;